import { RECIPES, getRecipe, totalMinutes } from "@/data/recipes";
import { recipesForIngredients } from "@/lib/recipes/search";

/**
 * DEMO MODE ONLY. These answers are pre-written by the Kitchen OS authors and
 * selected by simple keyword matching — they are NOT generated by an AI model.
 * The UI labels every demo answer accordingly.
 */

export interface DemoReply {
  text: string;
  recipeSlugs: string[];
}

const SUBSTITUTES: Record<string, string> = {
  "oyster sauce":
    "Instead of oyster sauce (per 1 tbsp):\n- 1 tbsp soy sauce + ½ tsp sugar, or\n- 1 tbsp hoisin sauce (sweeter), or\n- mushroom \"oyster\" sauce for a vegetarian swap.\nAdd a few drops of fish sauce if you want more savouriness.",
  "kecap manis":
    "Instead of kecap manis (per 2 tbsp):\nSimmer 2 tbsp soy sauce with 2 tbsp palm or brown sugar for 1–2 minutes until syrupy. Cool before using.",
  "fish sauce": "Instead of fish sauce: use soy sauce with a pinch of salt, or a little anchovy paste. Start with less and taste.",
  mirin: "Instead of mirin (per 1 tbsp): 1 tbsp dry sherry or sake + ½ tsp sugar, or 1 tbsp rice vinegar + 1 tsp sugar.",
  sake: "Instead of sake: dry sherry, dry white wine, or water with a few drops of rice vinegar.",
  buttermilk: "Instead of 250 ml buttermilk: stir 1 tbsp lemon juice or vinegar into 250 ml milk and wait 5 minutes.",
  gochujang: "Instead of gochujang (per 1 tbsp): 1 tsp chilli flakes + 1 tsp miso + ½ tsp sugar + a few drops of soy sauce.",
  cream: "Instead of cream in sauces or soups: whole milk with a knob of butter, evaporated milk, or coconut milk.",
  "palm sugar": "Instead of palm sugar: the same weight of dark brown sugar. Coconut sugar also works.",
  "shrimp paste": "Instead of shrimp paste (terasi): a little fish sauce or anchovy paste. For vegetarian, use white miso.",
  butter: "Instead of butter for cooking: oil works for frying. For baking, use the same weight of a block margarine or ¾ the weight of neutral oil.",
  egg: "Instead of 1 egg in baking: 1 tbsp ground flaxseed + 3 tbsp water (rest 5 min), or 60 g mashed banana or apple sauce.",
  "rice vinegar": "Instead of rice vinegar: apple cider vinegar or white wine vinegar with a pinch of sugar.",
};

const TECHNIQUES: Record<string, string> = {
  deglaze:
    "Deglazing means pouring liquid (wine, stock or water) into a hot pan after searing, then scraping up the browned bits. Those bits dissolve into a quick, flavourful sauce.",
  blanch:
    "Blanching is cooking food briefly in boiling salted water, then cooling it quickly in cold water. It keeps vegetables bright and crisp-tender.",
  sear: "Searing is browning food in a very hot pan with a little fat. Pat the food dry first and don't move it until a crust forms.",
  julienne: "Julienne means cutting food into thin matchsticks, about 3 mm thick and 5–6 cm long.",
  simmer: "Simmering is cooking just below boiling: small, gentle bubbles break the surface now and then.",
  emulsify:
    "Emulsifying is blending fat and water into one smooth sauce — like tossing pasta with starchy cooking water and oil until glossy.",
  fold:
    "Folding gently combines a light mixture (whipped egg whites, cream) into a heavier one. Cut down through the middle with a spatula and turn the bowl, so you keep the air.",
  "rest": "Resting meat for a few minutes after cooking lets the juices settle, so they stay in the meat when you slice it.",
};

const has = (q: string, ...words: string[]) => words.some((w) => q.includes(w));

function link(slugs: string[]): string[] {
  return slugs.filter((s) => !!getRecipe(s));
}

export function demoReply(input: string): DemoReply {
  const q = input.toLowerCase();

  // 1. Ingredient-based recommendations
  const withMatch = q.match(/(?:cook|make)\s+with\s+(.+)|i have\s+(.+)|using\s+(.+)/);
  if (withMatch) {
    const list = (withMatch[1] ?? withMatch[2] ?? withMatch[3] ?? "")
      .replace(/[?.!]/g, "")
      .split(/,|\band\b|&/)
      .map((s) => s.trim())
      .filter((s) => s.length > 1)
      .slice(0, 8);
    const ranked = recipesForIngredients(RECIPES, list).slice(0, 3);
    if (ranked.length) {
      const lines = ranked.map((r, i) => `${i + 1}. ${r.recipe.name} — uses ${r.matched.join(", ")} (${totalMinutes(r.recipe)} min)`);
      return {
        text: `From the Kitchen OS recipe library, these use what you have:\n${lines.join("\n")}\n\nOpen one below to see the full ingredient list.`,
        recipeSlugs: ranked.map((r) => r.recipe.slug),
      };
    }
    return {
      text: "I couldn't find a recipe in the library that uses those ingredients. Try naming one or two main ingredients, like “chicken and rice”.",
      recipeSlugs: [],
    };
  }

  // 2. Substitutions
  if (has(q, "replace", "substitute", "instead of", "swap", "pengganti", "ganti")) {
    const key = Object.keys(SUBSTITUTES).find((k) => q.includes(k));
    if (key) return { text: SUBSTITUTES[key], recipeSlugs: [] };
    return {
      text: `In demo mode I know substitutes for: ${Object.keys(SUBSTITUTES).join(", ")}. Ask, for example, “What can replace mirin?”`,
      recipeSlugs: [],
    };
  }

  // 3. Chicken smell
  if (has(q, "smell", "odor", "odour", "amis", "bau") && has(q, "chicken", "ayam")) {
    return {
      text: "To reduce the raw smell of chicken:\n1. Rinse briefly in cold water only if needed, then pat dry.\n2. Rub with salt and lime or lemon juice for 10 minutes, then rinse.\n3. Or marinate with ginger, garlic and a splash of rice wine.\n4. Trim off excess fat and skin, where most odour sits.\nA strong sour or sulphur smell means the chicken has spoiled — don't use it.",
      recipeSlugs: [],
    };
  }

  // 4. Dry chicken
  if (has(q, "dry", "tough", "kering", "alot") && has(q, "chicken", "ayam", "breast")) {
    return {
      text: "Common reasons chicken turns out dry:\n- Overcooking: take breast off the heat at 74°C (165°F) inside; thighs are more forgiving.\n- Too lean a cut: thighs stay juicier than breast.\n- No rest: rest 5 minutes before slicing.\n- Thick, uneven pieces: pound or butterfly breast to an even thickness.\nTip: brine in 1 litre water + 1 tbsp salt for 30–60 minutes before cooking.",
      recipeSlugs: link(["chicken-teriyaki", "roast-chicken-thighs"]),
    };
  }

  // 5. Restaurant-style fried rice
  if (has(q, "fried rice", "nasi goreng")) {
    return {
      text: "Restaurant-style fried rice comes down to:\n1. Cold, day-old rice so the grains stay separate.\n2. A very hot wok and only a few servings at a time.\n3. Cook the egg first, then add it back at the end.\n4. Season around the edge of the wok so the soy sauce sizzles.\n5. Spread the rice and let it sit a few seconds between tosses for smoky flavour.",
      recipeSlugs: link(["egg-fried-rice", "nasi-goreng", "kimchi-fried-rice"]),
    };
  }

  // 6. Meal planning / dinner for N
  const nMatch = q.match(/(?:for|untuk)\s+(\d+|two|three|four|five|six)\s*(?:people|persons|orang|guests)?/);
  if (has(q, "dinner", "meal plan", "menu", "plan", "makan malam", "weeknight")) {
    const words: Record<string, number> = { two: 2, three: 3, four: 4, five: 5, six: 6 };
    const n = nMatch ? Number(nMatch[1]) || words[nMatch[1]] || 3 : null;
    if (has(q, "weeknight", "three easy", "week")) {
      const picks = ["chicken-teriyaki", "tomato-egg-stir-fry", "aglio-olio"];
      return {
        text: "Three easy weeknight dinners, all under 30 minutes:\n1. Chicken Teriyaki with rice\n2. Tomato & Egg Stir-Fry\n3. Spaghetti Aglio e Olio\nCook extra rice on day 1 — it makes great fried rice later.",
        recipeSlugs: picks,
      };
    }
    const picks = ["soto-ayam", "gado-gado", "pisang-goreng"];
    return {
      text: `A relaxed Indonesian dinner${n ? ` for ${n}` : ""}:\n1. Soto Ayam (main)\n2. Gado-Gado (side)\n3. Pisang Goreng (dessert)\nOpen each recipe and set servings to ${n ?? "your guest count"} — quantities scale automatically.\nOrder: make the soup first; blanch vegetables while it simmers; fry the bananas just before serving.`,
      recipeSlugs: picks,
    };
  }

  // 7. Serving adjustments
  if (has(q, "serving", "scale", "double", "halve", "porsi")) {
    return {
      text: "Open any recipe and use the Servings − / + buttons. Every ingredient quantity updates instantly, and Cooking Mode uses the same amounts.\nFor big batches, cooking times can run a little longer — check doneness rather than the clock.",
      recipeSlugs: [],
    };
  }

  // 8. Techniques
  const technique = Object.keys(TECHNIQUES).find((k) => q.includes(k));
  if (technique) return { text: TECHNIQUES[technique], recipeSlugs: [] };

  // 9. Recipe generation request
  if (has(q, "recipe for", "how to make", "how do i make", "cara membuat", "resep")) {
    const words = q.replace(/[?.!]/g, "").split(/\s+/);
    const found = RECIPES.find((r) => words.some((w) => w.length > 3 && r.name.toLowerCase().includes(w)));
    if (found) {
      return { text: `Kitchen OS has a full step-by-step recipe for ${found.name}. Open it below, then press Start Cooking.`, recipeSlugs: [found.slug] };
    }
  }

  return {
    text:
      "This is Demo Mode, so I can only answer a small set of topics with pre-written tips: ingredient-based suggestions, substitutes, chicken smell or dryness, fried rice, dinner plans, servings and cooking techniques.\nTo ask anything, add an AI API key on the server (see README → AI Chef).",
    recipeSlugs: [],
  };
}
